/**
 * Markdown and Mermaid formatting helpers shared by the graph renderers: page
 * headers, maintenance footers, repository-relative links, and table cells.
 */

import { dirname, relative } from 'node:path'
import type { Pkg } from './gen-doc-graphs-shared.ts'

/** Open one generated page with its banner comment and title. */
export function generatedHeader(title: string): string[] {
  return [
    '<!-- Generated by scripts/gen-doc-graphs.ts - do not edit by hand.',
    '     Run `pnpm run gen-doc-graphs` to regenerate. -->',
    '',
    `# ${title}`,
    '',
  ]
}

/** Close one page with the line naming how its content is maintained. */
export function maintenanceFooter(source: string): string[] {
  return [`Maintenance mode: ${source}.`, '']
}

/** Link target for one graph page, relative to the docs directory. */
export function graphIndexLink(rel: string): string {
  return relative('docs', rel).replaceAll('\\', '/')
}

/** Link target from one rendering page to a repository file. */
export function linkFromDoc(docRel: string, targetRel: string): string {
  return relative(dirname(docRel), targetRel).replaceAll('\\', '/')
}

/** Escape a value for the inline code spans Mermaid node labels carry. */
export function mermaidCode(value: string): string {
  return `<code>${value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>`
}

/** Render one repository-relative markdown link. */
export function repoLink(path: string, label: string, up = '..'): string {
  return `[${label}](${up}/${path})`
}

/** Link a `file:line` source pointer, dropping the line for the href. */
export function sourceLink(source: string, up = '..'): string {
  return repoLink(source.split(':')[0] ?? source, `\`${source}\``, up)
}

/** Link one package, or render its bare name when the graph never saw it. */
export function pkgLink(pkg: Pkg | undefined, fallback: string, up = '..'): string {
  return pkg ? repoLink(pkg.rel, `\`${pkg.short}\``, up) : `\`${fallback}\``
}

/** Render a comma-separated package list, or a dash when it is empty. */
export function pkgList(names: string[] | undefined, pkgsByShort: Map<string, Pkg>): string {
  if (!names || names.length === 0) return '-'
  return names.map(name => pkgLink(pkgsByShort.get(name), name)).join(', ')
}

/** Escape one value for a markdown table cell. */
export function tableCell(value: string): string {
  return value.replace(/\|/g, '\\|').replace(/\n/g, '<br>')
}
